cd /app && cat > para.pl <<'PERL'
#!/usr/bin/perl
use strict; use warnings;
my %family;
open my $fh,'<','synonyms.txt' or die;
while(my $l=<$fh>){chomp $l; next unless $l=~/\S/; my @w=split/\s*,\s*/,$l; $family{$_}=\@w for @w;}
close $fh;
open my $in,'<','input.tex.bak' or die;
my $orig=do{local $/;<$in>}; close $in;
# split into lines
my @lines = split /\n/, $orig, -1;
print "total lines: ",scalar(@lines),"\n";
# paragraph = group of consecutive non-empty lines
my @para; # each: {startline, endline, text}
my $i=0;
while($i < @lines){
    if($lines[$i] =~ /^\s*$/){ $i++; next; }
    my $s=$i; my $text="";
    while($i<@lines && $lines[$i] !~ /^\s*$/){ $text .= ($text eq "" ? "" : "") . $lines[$i] . "\n"; $i++; }
    my $e=$i-1;
    push @para, {s=>$s+1, e=>$e+1, text=>$text};
}
# tokenize each paragraph, find occurrences
my $tok=0;
for my $p (0..$#para){
    my $t=$para[$p]{text};
    my @occ;
    while($t =~ /([A-Za-z]+)|([^A-Za-z]+)/g){
        $tok++;
        if(defined $1 && exists $family{$1}){ push @occ, $1; }
    }
    printf "para %d: lines %d-%d  words_tok~%d  occ(%d): %s\n",
        $p+1, $para[$p]{s}, $para[$p]{e}, $tok, scalar(@occ), join(',',@occ);
}
PERL
